-module(bmscl_route_refresh).
-behaviour(gen_server).

-export([start_link/0, refresh_now/0, status/0]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2, code_change/3]).

-record(state, {
    source = undefined,
    refresh_ms = 30000,
    subscribed = false,
    ready = false,
    last_error = undefined,
    last_version = 0,
    last_digest = undefined,
    last_schema = undefined,
    last_environment = undefined,
    last_success_ms = undefined
}).

start_link() ->
    gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

refresh_now() ->
    gen_server:call(?MODULE, refresh_now, infinity).

status() ->
    gen_server:call(?MODULE, status).

init([]) ->
    Source = application:get_env(bmscl_supervisor, route_source_module, undefined),
    RefreshMs = application:get_env(bmscl_supervisor, route_refresh_ms, 30000),
    State0 = #state{
        source = Source,
        refresh_ms = RefreshMs,
        ready = Source =:= undefined
    },
    State1 = maybe_subscribe(State0),
    self() ! refresh,
    {ok, State1}.

handle_call(refresh_now, _From, State0) ->
    {Reply, State1} = refresh(State0),
    {reply, Reply, State1};
handle_call(status, _From, State = #state{}) ->
    {reply, status_map(State), State};
handle_call(_Request, _From, State) ->
    {reply, {error, unsupported_call}, State}.

handle_cast(_Msg, State) -> {noreply, State}.

handle_info(refresh, State0) ->
    {_Reply, State1} = refresh(State0),
    schedule_refresh(State1#state.refresh_ms),
    {noreply, State1};
handle_info(bmscl_routes_changed, State) ->
    %% Pub/sub is deliberately only an invalidation signal. Always refetch the
    %% authoritative snapshot; never trust message ordering, delivery, or body.
    self() ! refresh,
    {noreply, State};
handle_info({bmscl_routes_changed, _Version}, State) ->
    self() ! refresh,
    {noreply, State};
handle_info({bmscl_route_source_disconnected, Reason}, State0) ->
    %% Keep serving the last atomically installed table while retrying the
    %% subscription and periodic reconciliation. Readiness stays true after the
    %% first successful snapshot, while source connectivity is separately visible.
    State1 = maybe_subscribe(State0#state{
        subscribed = false,
        last_error = {source_disconnected, Reason}
    }),
    {noreply, State1};
handle_info(_Info, State) -> {noreply, State}.

terminate(_Reason, _State) -> ok.
code_change(_OldVsn, State, _Extra) -> {ok, State}.

maybe_subscribe(State = #state{source = undefined}) -> State;
maybe_subscribe(State = #state{source = Source}) when is_atom(Source) ->
    try Source:subscribe(self()) of
        ok -> State#state{subscribed = true, last_error = undefined};
        {ok, _Handle} -> State#state{subscribed = true, last_error = undefined};
        {error, Reason} -> State#state{subscribed = false, last_error = {subscribe, Reason}};
        Other -> State#state{subscribed = false, last_error = {subscribe, {unexpected, Other}}}
    catch
        Class:Reason -> State#state{subscribed = false, last_error = {subscribe, {Class, Reason}}}
    end;
maybe_subscribe(State) ->
    State#state{last_error = invalid_route_source_module}.

refresh(State = #state{source = undefined}) ->
    {{ok, disabled}, State#state{ready = true}};
refresh(State0 = #state{source = Source}) when is_atom(Source) ->
    try Source:snapshot() of
        {ok, Meta, Routes} when is_map(Meta), is_map(Routes) ->
            case validate_snapshot_meta(Meta) of
                {ok, Version} -> install_snapshot(Version, Routes, Meta, State0);
                {error, Reason} ->
                    {{error, Reason}, State0#state{last_error = {validation, Reason}}}
            end;
        {ok, Version, Routes} when is_integer(Version), Version >= 0, is_map(Routes) ->
            %% Backward-compatible path for simple/test adapters.
            install_snapshot(Version, Routes, #{version => Version}, State0);
        {error, Reason} ->
            {{error, Reason}, State0#state{last_error = {snapshot, Reason}}};
        Other ->
            Reason = {unexpected_snapshot_result, Other},
            {{error, Reason}, State0#state{last_error = {snapshot, Reason}}}
    catch
        Class:Reason ->
            Error = {Class, Reason},
            {{error, Error}, State0#state{last_error = {snapshot, Error}}}
    end;
refresh(State) ->
    {{error, invalid_route_source_module}, State#state{last_error = invalid_route_source_module}}.

validate_snapshot_meta(Meta) ->
    case maps:get(version, Meta, undefined) of
        Version when is_integer(Version), Version >= 0 ->
            case validate_optional_digest(maps:get(snapshot_sha256, Meta, undefined)) of
                ok -> {ok, Version};
                Error -> Error
            end;
        _ -> {error, invalid_route_snapshot_version}
    end.

validate_optional_digest(undefined) -> ok;
validate_optional_digest(Digest) when is_binary(Digest), byte_size(Digest) =:= 64 ->
    case lists:all(fun is_lower_hex/1, binary_to_list(Digest)) of
        true -> ok;
        false -> {error, invalid_route_snapshot_digest}
    end;
validate_optional_digest(_) -> {error, invalid_route_snapshot_digest}.

is_lower_hex(C) when C >= $0, C =< $9 -> true;
is_lower_hex(C) when C >= $a, C =< $f -> true;
is_lower_hex(_) -> false.

install_snapshot(Version, Routes, Meta, State0) ->
    case bmscl_route_table:replace_snapshot(Version, Routes) of
        {ok, Result} ->
            State1 = mark_success(Version, Meta, State0),
            {{ok, Result}, State1};
        {error, {stale_route_snapshot, Current, _}} ->
            %% The installed table is newer than this source response. Keep the
            %% current table and expose the stale source condition for health/audit.
            Reason = {stale_route_snapshot, Current, Version},
            {{ok, stale_ignored}, State0#state{
                last_version = Current,
                last_error = {validation, Reason}
            }};
        {error, Reason} ->
            {{error, Reason}, State0#state{last_error = {install, Reason}}}
    end.

mark_success(Version, Meta, State) ->
    State#state{
        ready = true,
        last_error = undefined,
        last_version = Version,
        last_digest = maps:get(snapshot_sha256, Meta, State#state.last_digest),
        last_schema = maps:get(schema, Meta, State#state.last_schema),
        last_environment = maps:get(environment, Meta, State#state.last_environment),
        last_success_ms = erlang:monotonic_time(millisecond)
    }.

status_map(State) ->
    #{
        source => State#state.source,
        source_status => source_status(State#state.source),
        subscribed => State#state.subscribed,
        ready => State#state.ready,
        last_error => State#state.last_error,
        last_version => State#state.last_version,
        snapshot_sha256 => State#state.last_digest,
        schema => State#state.last_schema,
        environment => State#state.last_environment,
        last_success_ms => State#state.last_success_ms,
        snapshot_age_ms => snapshot_age_ms(State#state.last_success_ms)
    }.

source_status(undefined) -> disabled;
source_status(Source) when is_atom(Source) ->
    case erlang:function_exported(Source, status, 0) of
        false -> unavailable;
        true ->
            try Source:status()
            catch Class:Reason -> {error, {Class, Reason}}
            end
    end;
source_status(_) -> invalid.

snapshot_age_ms(undefined) -> undefined;
snapshot_age_ms(LastSuccess) ->
    erlang:max(0, erlang:monotonic_time(millisecond) - LastSuccess).

schedule_refresh(Ms) when is_integer(Ms), Ms > 0 ->
    erlang:send_after(Ms, self(), refresh),
    ok;
schedule_refresh(_) ->
    erlang:send_after(30000, self(), refresh),
    ok.

-module(bmscl_route_table).
-behaviour(gen_server).

-export([start_link/0, lookup/1, resolve/2, snapshot/0, replace_snapshot/2, apply_delta/2]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2, code_change/3]).

-record(state, {
    version = 0,
    initialized = false,
    routes = #{},
    holds = #{}
}).

start_link() ->
    gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

lookup(Key) ->
    gen_server:call(?MODULE, {lookup, Key}).

resolve(Method, Path) ->
    gen_server:call(?MODULE, {resolve, Method, Path}).

snapshot() ->
    gen_server:call(?MODULE, snapshot).

replace_snapshot(Version, Routes) ->
    gen_server:call(?MODULE, {replace_snapshot, Version, Routes}, infinity).

apply_delta(Version, Ops) ->
    gen_server:call(?MODULE, {apply_delta, Version, Ops}, infinity).

init([]) ->
    {ok, #state{}}.

handle_call({lookup, Key}, _From, State = #state{routes = Routes}) ->
    {reply, maps:find(Key, Routes), State};
handle_call({resolve, Method0, Path0}, _From, State = #state{routes = Routes}) ->
    Reply = case normalize_key(Method0, Path0) of
        {error, Reason} -> {error, Reason};
        {ok, {Method, Path} = Key} ->
            case maps:find(Key, Routes) of
                {ok, Target} -> {ok, Target};
                error when Method =/= <<"ANY">> ->
                    case maps:find({<<"ANY">>, Path}, Routes) of
                        {ok, Target} -> {ok, Target};
                        error -> {error, route_not_found}
                    end;
                error -> {error, route_not_found}
            end
    end,
    {reply, Reply, State};
handle_call(snapshot, _From, State = #state{version = Version, routes = Routes}) ->
    {reply, {ok, Version, Routes}, State};
handle_call({replace_snapshot, Version, Routes}, _From,
            State0 = #state{version = Current, initialized = Initialized})
  when is_integer(Version), Version >= 0, is_map(Routes) ->
    case Initialized of
        false ->
            %% Version zero is a valid first authoritative generation. Keep a
            %% separate initialization bit so the empty bootstrap table is not
            %% mistaken for an already-applied version-0 snapshot.
            case install_routes(Version, Routes, State0) of
                {ok, State1} -> {reply, {ok, updated}, State1};
                {error, Reason} -> {reply, {error, Reason}, State0}
            end;
        true ->
            case Version < Current of
                true ->
                    {reply, {error, {stale_route_snapshot, Current, Version}}, State0};
                false when Version =:= Current ->
                    {reply, {ok, unchanged}, State0};
                false ->
                    case install_routes(Version, Routes, State0) of
                        {ok, State1} -> {reply, {ok, updated}, State1};
                        {error, Reason} -> {reply, {error, Reason}, State0}
                    end
            end
    end;
handle_call({replace_snapshot, _Version, _Routes}, _From, State) ->
    {reply, {error, invalid_route_snapshot}, State};
handle_call({apply_delta, Version, Ops}, _From,
            State0 = #state{version = Current, initialized = Initialized, routes = Routes})
  when is_integer(Version), Version >= 0, is_list(Ops) ->
    case Initialized of
        false ->
            %% Pub/Sub/deltas cannot establish the initial truth. The caller must
            %% fetch a complete authoritative snapshot first.
            {reply, {error, {route_snapshot_required, Version}}, State0};
        true ->
            case Version of
                Current ->
                    {reply, {ok, unchanged}, State0};
                _ when Version =:= Current + 1 ->
                    case apply_ops(Ops, Routes) of
                        {ok, Routes1} ->
                            case install_routes(Version, Routes1, State0) of
                                {ok, State1} -> {reply, {ok, updated}, State1};
                                {error, Reason} -> {reply, {error, Reason}, State0}
                            end;
                        {error, Reason} ->
                            {reply, {error, Reason}, State0}
                    end;
                _ when Version < Current ->
                    {reply, {error, {stale_route_delta, Current, Version}}, State0};
                _ ->
                    %% A gap means at least one pub/sub message may have been missed.
                    %% The caller must fetch and install a full authoritative snapshot.
                    {reply, {error, {route_version_gap, Current, Version}}, State0}
            end
    end;
handle_call({apply_delta, _Version, _Ops}, _From, State) ->
    {reply, {error, invalid_route_delta}, State};
handle_call(_Request, _From, State) ->
    {reply, {error, unsupported_call}, State}.

handle_cast(_Msg, State) -> {noreply, State}.
handle_info(_Info, State) -> {noreply, State}.
terminate(_Reason, State) ->
    release_all_holds(State#state.holds),
    ok.
code_change(_OldVsn, State, _Extra) -> {ok, State}.

install_routes(Version, Routes0, State0) ->
    case normalize_routes(Routes0) of
        {error, Reason} -> {error, Reason};
        {ok, Routes} ->
            Deps = deployment_set(Routes),
            case acquire_holds(Deps, State0#state.holds) of
                {error, Reason} -> {error, Reason};
                {ok, Holds1} ->
                    release_removed_holds(State0#state.holds, Deps),
                    Holds2 = maps:with(maps:keys(Deps), Holds1),
                    {ok, State0#state{
                        version = Version,
                        initialized = true,
                        routes = Routes,
                        holds = Holds2
                    }}
            end
    end.

normalize_routes(Routes) ->
    maps:fold(
      fun(Key0, Target0, {ok, Acc}) ->
              case normalize_route(Key0, Target0) of
                  {error, Reason} -> {error, Reason};
                  {ok, Key, Target} ->
                      case maps:is_key(Key, Acc) of
                          true -> {error, {duplicate_route, Key}};
                          false -> {ok, maps:put(Key, Target, Acc)}
                      end
              end;
         (_Key, _Target, Error) -> Error
      end,
      {ok, #{}},
      Routes).

normalize_route(Key0, Target0) when is_map(Target0) ->
    case normalize_route_key(Key0) of
        {error, Reason} -> {error, Reason};
        {ok, Key} ->
            case maps:find(deployment_id, Target0) of
                {ok, DeploymentId} when is_binary(DeploymentId), byte_size(DeploymentId) > 0 ->
                    normalize_optional_actor_path(Key, DeploymentId, Target0);
                {ok, DeploymentId} when is_atom(DeploymentId) ->
                    normalize_optional_actor_path(Key, DeploymentId, Target0);
                _ -> {error, invalid_deployment_id}
            end
    end;
normalize_route(_Key, _Target) ->
    {error, invalid_route_target}.

normalize_optional_actor_path(Key, DeploymentId, Target0) ->
    case maps:find(actor_path, Target0) of
        error -> {ok, Key, Target0#{deployment_id => DeploymentId}};
        {ok, Actor0} ->
            case normalize_actor_path(Actor0) of
                {ok, ActorPath} ->
                    {ok, Key, Target0#{deployment_id => DeploymentId, actor_path => ActorPath}};
                {error, Reason} -> {error, Reason}
            end
    end.

normalize_route_key({Method, Path}) -> normalize_key(Method, Path);
normalize_route_key(_) -> {error, invalid_route_key}.

normalize_key(Method0, Path0) ->
    case {normalize_method(Method0), normalize_path(Path0)} of
        {{ok, Method}, {ok, Path}} -> {ok, {Method, Path}};
        {{error, Reason}, _} -> {error, Reason};
        {_, {error, Reason}} -> {error, Reason}
    end.

normalize_method(Method) when is_atom(Method) -> normalize_method(atom_to_binary(Method, utf8));
normalize_method(Method) when is_list(Method) -> normalize_method(unicode:characters_to_binary(Method));
normalize_method(Method) when is_binary(Method), byte_size(Method) > 0, byte_size(Method) =< 16 ->
    Upper = unicode:characters_to_binary(string:uppercase(binary_to_list(Method))),
    case valid_method(Upper) of
        true -> {ok, Upper};
        false -> {error, invalid_http_method}
    end;
normalize_method(_) -> {error, invalid_http_method}.

valid_method(<<"ANY">>) -> true;
valid_method(Method) ->
    lists:member(Method, [<<"GET">>, <<"HEAD">>, <<"POST">>, <<"PUT">>,
                          <<"PATCH">>, <<"DELETE">>, <<"OPTIONS">>, <<"CONNECT">>,
                          <<"TRACE">>]).

normalize_path(Path) when is_list(Path) -> normalize_path(unicode:characters_to_binary(Path));
normalize_path(<<"/", _/binary>> = Path) when byte_size(Path) =< 4096 ->
    case binary:match(Path, <<0>>) =:= nomatch andalso
         binary:match(Path, <<"?">>) =:= nomatch andalso
         binary:match(Path, <<"#">>) =:= nomatch of
        true -> {ok, Path};
        false -> {error, invalid_http_path}
    end;
normalize_path(_) -> {error, invalid_http_path}.

normalize_actor_path(Path) when is_list(Path) -> normalize_actor_path(unicode:characters_to_binary(Path));
normalize_actor_path(Path) when is_binary(Path), byte_size(Path) > 0, byte_size(Path) =< 1024 ->
    case Path of
        <<"/", _/binary>> -> {error, invalid_actor_path};
        _ ->
            Segments = binary:split(Path, <<"/">>, [global]),
            case lists:all(fun valid_actor_segment/1, Segments) of
                true -> {ok, Path};
                false -> {error, invalid_actor_path}
            end
    end;
normalize_actor_path(_) -> {error, invalid_actor_path}.

valid_actor_segment(<<>>) -> false;
valid_actor_segment(<<".">>) -> false;
valid_actor_segment(<<"..">>) -> false;
valid_actor_segment(Segment) -> binary:match(Segment, <<0>>) =:= nomatch.

deployment_set(Routes) ->
    maps:fold(
      fun(_Key, Target, Acc) -> maps:put(maps:get(deployment_id, Target), true, Acc) end,
      #{},
      Routes).

acquire_holds(Deps, Existing) ->
    Needed = [Id || Id <- maps:keys(Deps), not maps:is_key(Id, Existing)],
    acquire_holds(Needed, Existing, []).

acquire_holds([], Holds, _Acquired) -> {ok, Holds};
acquire_holds([Id | Rest], Holds0, Acquired) ->
    Result = try bmscl_deployment_manager:hold_deployment(Id)
             catch exit:ExitReason -> {error, {deployment_manager_unavailable, ExitReason}}
             end,
    case Result of
        {ok, Pin} ->
            acquire_holds(Rest, maps:put(Id, Pin, Holds0), [{Id, Pin} | Acquired]);
        {error, Reason} ->
            lists:foreach(fun({_AcquiredId, Pin}) -> release_pin(Pin) end, Acquired),
            {error, {route_target_unavailable, Id, Reason}}
    end.

release_removed_holds(Holds, NewDeps) ->
    maps:foreach(
      fun(Id, Pin) ->
          case maps:is_key(Id, NewDeps) of
              true -> ok;
              false -> release_pin(Pin)
          end
      end,
      Holds).

release_all_holds(Holds) ->
    maps:foreach(fun(_Id, Pin) -> release_pin(Pin) end, Holds).

release_pin(Pin) ->
    _ = try bmscl_deployment_manager:release_pin(Pin)
        catch exit:_ -> ok
        end,
    ok.

apply_ops([], Routes) -> {ok, Routes};
apply_ops([{put, Key, Target} | Rest], Routes) ->
    apply_ops(Rest, maps:put(Key, Target, Routes));
apply_ops([{delete, Key} | Rest], Routes) ->
    apply_ops(Rest, maps:remove(Key, Routes));
apply_ops([Bad | _], _Routes) ->
    {error, {invalid_route_operation, Bad}}.

-module(bmscl_tenancy_policy).

-export([class/1, validate/2]).

%% Durable actors/critical sections are single-tenant per BEAM OS process.
%% Lambda is the flagship FaaS product: free may multiplex tenants in one BEAM
%% process, while pro is tenant-dedicated.
class(durable_actor_v1) -> tenant_dedicated;
class(critical_section_v1) -> tenant_dedicated;
class(lambda_free_v1) -> mixed_tenants;
class(lambda_pro_v1) -> tenant_dedicated;
class(_) -> undefined.

validate(Profile, Requested) ->
    case class(Profile) of
        undefined -> {error, {unknown_tenancy_profile, Profile}};
        Requested -> ok;
        Required -> {error, {tenancy_class_mismatch, Required, Requested}}
    end.
